   200  otError SubMac::Send(void)
   201  {
   202      otError error = OT_ERROR_NONE;
   203
   204      switch (mState)
   205      {
   206      case kStateDisabled:
   207      case kStateCsmaBackoff:
   208      case kStateTransmit:
   209      case kStateEnergyScan:
   210          ExitNow(error = OT_ERROR_INVALID_STATE);
   211          break;
   212
   213      case kStateSleep:
   214      case kStateReceive:
   215          break;
   216      }
   217
   218      mCsmaBackoffs    = 0;
   219      mTransmitRetries = 0;
   220      StartCsmaBackoff();
   221
   222  exit:
   223      return error;
   224  }
