   226  void SubMac::StartCsmaBackoff(void)
   227  {
   228      uint32_t backoff;
   229      uint32_t backoffExponent = kMinBE + mTransmitRetries + mCsmaBackoffs;
   230
   231      SetState(kStateCsmaBackoff);
   232
   233      VerifyOrExit(ShouldHandleCsmaBackOff(), BeginTransmit());
   234
   235  #if OPENTHREAD_CONFIG_DISABLE_CSMA_CA_ON_LAST_ATTEMPT
   236      if ((mTransmitRetries > 0) && (mTransmitRetries == mTransmitFrame.GetMaxFrameRetries()))
   237      {
   238          BeginTransmit();
   239          ExitNow();
   240      }
   241  #endif
   242
   243      if (backoffExponent > kMaxBE)
   244      {
   245          backoffExponent = kMaxBE;
   246      }
   247
   248      backoff = Random::GetUint32InRange(0, static_cast<uint32_t>(1UL << backoffExponent));
   249      backoff *= (static_cast<uint32_t>(kUnitBackoffPeriod) * OT_RADIO_SYMBOL_TIME);
   250
   251      if (mRxOnWhenBackoff)
   252      {
   253          otPlatRadioReceive(&GetInstance(), mTransmitFrame.GetChannel());
   254      }
   255      else
   256      {
   257          otPlatRadioSleep(&GetInstance());
   258      }
